widgets_values:
{
  "整体风格": "3D CG写实数字人，古代东方市井武侠质感；青绿绸缎、暗色劲装、粗布短褐与补丁破衣质感分明；分镜1-2为白天硬日光，分镜3-5为夜晚灯火与红灯笼暖光；气氛从白日密谋转入夜半灌酒、行刺惊扰，收尾乞讨施粥",
  "角色图片": {
    "杀手": "中年男子，黑发高束成髻，黑绳垂落，面容肃冷，穿深蓝近黑交领短袍，肩披灰黑双色短披风，腰系黑皮带与暗红绳穗，小臂缠黑布，胯佩黑鞘单刀，暗红缠柄",
    "地主": "中年男子，面容憨厚略带风霜，短黑发向上梳理，留短须茬，穿米褐色粗布交领短袖布扣衫，下着深灰粗布短裤，足蹬黑布薄底鞋",
    "店小二": "约十岁女孩，双丫髻，眉眼机灵带笑意，穿青蓝交领短褐与短裤，腰系污白破边围裙，足蹬草编凉鞋，神色表面乖巧",
    "酒店老板": "中年圆脸，八字须与小山羊胡，青绿暗花瓜皮帽顶红珠，暗青绿暗花长袍，银白盘扣立领，浅灰宽袖边，腰挂银灰纹钱袋，黑布白底鞋",
    "乞丐女孩": "约八九岁女孩，黑发乱束高髻碎发垂额，脸颊淡污痕，穿灰褐破旧短褂短裤，多处浅色补丁，腰系粗麻绳，足蹬草编凉鞋，眼神警惕倔强"
  },
  "场景图片": {
    "春香酒楼": "夜色深蓝的石板窄巷，青瓦木构两层门面，门楣横匾「春香酒楼」金字，两侧竖匾对联，檐下两盏大红纱灯垂黄穗，暖红光洒满门前青石。木门半开，内里透出金黄灯火；门右停一辆黑顶马车，车灯微明，远处街巷亦有红灯笼与闲逛野狗，市井夜景静谧",
    "杀手住所": "高夯土墙围起的僻静小院，青灰砖小平房，深色瓦檐，木门半掩贴白纸帖，旁有纸糊方格木窗。檐下摆木板床与薄褐褥枕，院中粗木桌放褐陶提梁壶，旁有小木凳。石砖地缝生苔，左角一株小树根脚围石，白天硬日光斜照，明暗反差大，冷清隐蔽",
    "酒楼内部": "酒楼内堂（勿拍门外夜街与门匾外景）；白天时左侧木格花窗泻入强烈暖阳光柱、尘埃浮动；夜晚时窗外墨蓝、以室内油灯与柜前暖光为主。右侧长柜与多层木架堆满陶碗酒坛，斑驳白墙正中贴「春酒春」大字，灰石地砖，剥落红漆木柱，方桌长凳与陶壶酒碗"
  },
  "镜头规则": "各分镜均使用越肩镜头硬切，只切说话人面部特写；场景与人物引用统一写尖括号，如 <酒楼内部>、<酒店老板>，须与角色图片/场景图片名称一致；同一分镜内时段、衣着、站位与场景不变；对白口型同步，单句控制在五秒内说完",
  "分镜序列": {
    "分镜1": [
      {
        "编号": 1,
        "时长": "3s",
        "镜头": "越肩硬切，<地主>面部特写",
        "画面": "白天。<酒楼内部>角落方桌，木格窗阳光柱斜照，<地主>与<店小二>对坐密谋。焦点在<地主>：端起酒碗虚掩嘴边，眼神阴沉，嘴唇微动",
        "对白": {
          "地主": "今夜把掌柜灌醉，亥时动手。"
        },
        "声音": "白日酒楼低语、碗沿轻碰、窗外市井远响，对白压低清晰，口型同步"
      },
      {
        "编号": 2,
        "时长": "2s",
        "镜头": "越肩硬切，<店小二>面部特写",
        "画面": "仍是白天，仍在<酒楼内部>，切到<店小二>面部，青衣围裙女孩凑近点头，表面乖巧，眼神发亮，后景长柜酒坛",
        "对白": {
          "店小二": "好酒备足了，灌醉他就行。"
        },
        "声音": "接续白日酒楼环境音，童声压低带笑意，口型同步，停在密谋对视"
      }
    ],
    "分镜2": [
      {
        "编号": 1,
        "时长": "3s",
        "镜头": "越肩硬切，<地主>面部特写",
        "画面": "白天。<杀手住所>檐下硬日影，木板床与陶壶虚焦在侧，<地主>对<杀手>下令。焦点在<地主>：压低嗓音，神色阴沉，手指侧门方向",
        "对白": {
          "地主": "小二灌醉他。你侧门进，下手干净。"
        },
        "声音": "小院蝉鸣、衣料轻擦，对白压低清晰，口型同步"
      },
      {
        "编号": 2,
        "时长": "2s",
        "镜头": "越肩硬切，<杀手>面部特写",
        "画面": "仍是白天，仍在<杀手住所>，切到<杀手>面部，拇指按刀柄，微微颔首，眼神肃冷应令",
        "对白": {
          "杀手": "得令。亥时必到。"
        },
        "声音": "接续小院日间环境音、刀鞘轻碰，嗓音低沉，口型同步，停在短暂对视"
      }
    ],
    "分镜3": [
      {
        "编号": 1,
        "时长": "2s",
        "镜头": "越肩硬切，<店小二>面部特写",
        "画面": "夜晚。<酒楼内部>中堂，窗外墨蓝，油灯暖光。<店小二>对<酒店老板>殷勤劝酒，双手捧酒碗凑近，笑得讨好",
        "对白": {
          "店小二": "掌柜的，这碗是今儿最好的！"
        },
        "声音": "夜店劝酒声、酒液入碗、远处更鼓隐约，口型同步"
      },
      {
        "编号": 2,
        "时长": "2s",
        "镜头": "越肩硬切，<酒店老板>面部特写",
        "画面": "仍是夜晚，仍在<酒楼内部>，切到<酒店老板>面部，已有醉意，憨笑接碗仰头灌下，拍案得意，眼神发糊，墙上「春酒春」字幅虚焦",
        "对白": {
          "酒店老板": "好！再满三碗也不醉！"
        },
        "声音": "灌酒声、拍案轻响、老板含糊大笑，口型同步"
      }
    ],
    "分镜4": [
      {
        "编号": 1,
        "时长": "3s",
        "镜头": "越肩硬切，<杀手>面部特写",
        "画面": "夜晚。<酒楼内部>暗角，<酒店老板>已醉倒桌旁。<杀手>俯身拔刀，刀尖将落，眼神杀意",
        "对白": {
          "杀手": "亥时到了，一刀了结。"
        },
        "声音": "夜半油灯噼啪、拔刀出鞘轻响，对白冷厉，口型同步"
      },
      {
        "编号": 2,
        "时长": "3s",
        "镜头": "越肩硬切，<杀手>面部特写",
        "画面": "仍是夜晚，仍在<酒楼内部>。门外突传敲门声，<杀手>刀尖一顿，侧耳辨出有人，脸色发白，怕被发现，立刻收刀转身从侧门逃窜",
        "对白": {
          "杀手": "有人？！别被撞见——"
        },
        "声音": "急促敲门自门外传入、杀手倒吸气、刀鞘收回与慌乱逃窜脚步，口型同步"
      }
    ],
    "分镜5": [
      {
        "编号": 1,
        "时长": "3s",
        "镜头": "越肩硬切，<乞丐女孩>面部特写",
        "画面": "夜晚。<春香酒楼>门外，大红灯笼映红石板，<乞丐女孩>捂着空肚子连连敲半掩木门，补丁破衣，脸色发白，眼神可怜又急切",
        "对白": {
          "乞丐女孩": "掌柜行行好，给口热饭吧……"
        },
        "声音": "木门连击、夜巷犬吠远响、灯笼纸轻颤，童声虚弱带哭腔，口型同步"
      },
      {
        "编号": 2,
        "时长": "3s",
        "镜头": "越肩硬切，<酒店老板>面部特写",
        "画面": "夜晚，门内<酒楼内部>暖光。<酒店老板>酒意未消却已被敲门惊醒坐起，看向门外瘦弱<乞丐女孩>，心软抬手示意进来吃饭，旁有热汤饭菜",
        "对白": {
          "酒店老板": "孩子别跪，进来吃饭。"
        },
        "声音": "门轴轻响、碗筷轻放、热汤冒气，嗓音温和带醉意，口型同步"
      }
    ]
  }
}
